#!/usr/bin/env bash

# Config helpers own the portable TOML defaults and the resolved shell snapshot
# used by the CLI and diagnostics modules.

default_config_toml() {
  cat <<'EOF'
# Tmux Whisper configuration (TOML)
# Generated by `tmux-whisper`; safe to edit.

[meta]
config_version = 1

[audio]
source = "auto"
silence_trim = false
silence_trim_mode = "edges"
silence_threshold_db = -60
silence_min_ms = 250
silence_keep_ms = 50

[clean]
repeats_level = 1

[history]
retention_days = 7
audio_retention_days = 2

[swift_parakeet]
model_path = ""
model_version = ""
socket_path = "~/.config/dictate/.cache/tmux-whisperd.sock"

[postprocess]
enabled = false
llm = "gpt-oss-120b"
max_tokens = 3000
chunk_words = 700
budget_long_words_threshold = 120

[inline]
autosend = true
process_sound = true
paste_target = "current"
send_mode = "enter"

[tmux]
autosend = true
paste_target = "origin"
postprocess = false
process_sound = true
mode = "code"
send_mode = "auto"

[debug]
keep_logs = false

[integrations.swiftbar]
enabled = true

[ui.keybinds]
tmux = "F12"
inline = "F11"

[ui.icons]
recording = "🔴"
processing = "🔲"
ready = "🔳"
error = "⚠️"
base = ""
code = ""
long = ""
email = ""
chat = ""
linkedin = ""
twitter = ""
cancel = "🚫"

[audio.sounds]
cancel = "~/.local/share/sounds/dictate/cancel.wav"
cancel_enabled = true
enabled = true
error = "~/.local/share/sounds/dictate/error.wav"
error_enabled = true
process = "~/.local/share/sounds/dictate/process.wav"
process_enabled = true
start = "~/.local/share/sounds/dictate/start.wav"
start_enabled = true
stop = "~/.local/share/sounds/dictate/stop.wav"
stop_enabled = true

[postprocess.budget_profiles.long]
chunk_words = 1000
llm = "gpt-oss-120b"
max_tokens = 5200

[postprocess.budget_profiles.short]
chunk_words = 700
llm = "gpt-oss-120b"
max_tokens = 2000
EOF
}

config_ensure() {
  [[ -f "$DICTATE_CONFIG_FILE" ]] && return 0
  mkdir -p "$(dirname "$DICTATE_CONFIG_FILE")"
  default_config_toml >"$DICTATE_CONFIG_FILE"
}

config_load() {
  need python3
  config_ensure
  eval "$(
    python3 - "$DICTATE_CONFIG_FILE" <<'PYEOF'
import os, shlex, sys, tomllib

path = os.path.expanduser(sys.argv[1])
parse_error = ""
try:
  with open(path, "rb") as f:
    cfg = tomllib.load(f) or {}
except tomllib.TOMLDecodeError as exc:
  cfg = {}
  parse_error = str(exc).replace("\n", " ")

def get(path, default=None):
  cur = cfg
  for part in path.split("."):
    if not isinstance(cur, dict) or part not in cur:
      return default
    cur = cur[part]
  return cur

def b(v, default=False):
  if v is None:
    return default
  return bool(v)

out = {
  "CFG_CONFIG_PARSE_ERROR": parse_error,
  "CFG_META_CONFIG_VERSION": str(get("meta.config_version", "")) if isinstance(get("meta.config_version", ""), int) else "",
  "CFG_AUDIO_SOURCE": str(get("audio.source", "auto")),
  "CFG_AUDIO_DEVICE_NAME": str(get("audio.device_name", "")),
  "CFG_AUDIO_MAC_NAME": str(get("audio.mac_name", "MacBook Air Microphone")),
  "CFG_AUDIO_IPHONE_NAME": str(get("audio.iphone_name", "")),
  "CFG_AUDIO_DEVICE_INDEX": str(get("audio.device_index", "")) if get("audio.device_index", None) is not None else "",
  "CFG_AUDIO_SILENCE_TRIM": "1" if b(get("audio.silence_trim", False), False) else "0",
  "CFG_AUDIO_SILENCE_TRIM_MODE": str(get("audio.silence_trim_mode", "edges")),
  "CFG_AUDIO_SILENCE_THRESHOLD_DB": str(get("audio.silence_threshold_db", "-60")),
  "CFG_AUDIO_SILENCE_MIN_MS": str(get("audio.silence_min_ms", "250")),
  "CFG_AUDIO_SILENCE_KEEP_MS": str(get("audio.silence_keep_ms", "50")),
  "CFG_AUDIO_SOUNDS_START": str(get("audio.sounds.start", "")),
  "CFG_AUDIO_SOUNDS_STOP": str(get("audio.sounds.stop", "")),
  "CFG_AUDIO_SOUNDS_PROCESS": str(get("audio.sounds.process", "")),
  "CFG_AUDIO_SOUNDS_ERROR": str(get("audio.sounds.error", "")),
  "CFG_AUDIO_SOUNDS_CANCEL": str(get("audio.sounds.cancel", "")),
  "CFG_AUDIO_SOUNDS_ENABLED": "1" if b(get("audio.sounds.enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_START_ENABLED": "1" if b(get("audio.sounds.start_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_STOP_ENABLED": "1" if b(get("audio.sounds.stop_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_PROCESS_ENABLED": "1" if b(get("audio.sounds.process_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_ERROR_ENABLED": "1" if b(get("audio.sounds.error_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_CANCEL_ENABLED": "1" if b(get("audio.sounds.cancel_enabled", True), True) else "0",
  "CFG_HISTORY_RETENTION_DAYS": str(get("history.retention_days", "7")),
  "CFG_HISTORY_AUDIO_RETENTION_DAYS": str(get("history.audio_retention_days", "2")),
  "CFG_SWIFT_PARAKEET_MODEL_PATH": str(get("swift_parakeet.model_path", "")),
  "CFG_SWIFT_PARAKEET_MODEL_VERSION": str(get("swift_parakeet.model_version", "")),
  "CFG_SWIFT_PARAKEET_SOCKET_PATH": str(get("swift_parakeet.socket_path", "~/.config/dictate/.cache/tmux-whisperd.sock")),
  "CFG_POSTPROCESS_ENABLED": "1" if b(get("postprocess.enabled", False), False) else "0",
  "CFG_POSTPROCESS_LLM": str(get("postprocess.llm", "gpt-oss-120b")),
  "CFG_POSTPROCESS_MAX_TOKENS": str(get("postprocess.max_tokens", "")),
  "CFG_POSTPROCESS_CHUNK_WORDS": str(get("postprocess.chunk_words", "")),
  "CFG_POSTPROCESS_BUDGET_LONG_WORDS_THRESHOLD": str(get("postprocess.budget_long_words_threshold", "120")),
  "CFG_POSTPROCESS_MODE_LLM_OVERRIDES": "",
  "CFG_POSTPROCESS_BUDGET_PROFILE_LLM_OVERRIDES": "",
  "CFG_POSTPROCESS_BUDGET_PROFILE_MAX_TOKENS_OVERRIDES": "",
  "CFG_POSTPROCESS_BUDGET_PROFILE_CHUNK_WORDS_OVERRIDES": "",
  "CFG_INLINE_AUTOSEND": "1" if b(get("inline.autosend", True), True) else "0",
  "CFG_INLINE_PROCESS_SOUND": "1" if b(get("inline.process_sound", True), True) else "0",
  "CFG_INLINE_PASTE_TARGET": str(get("inline.paste_target", "current")),
  "CFG_INLINE_SEND_MODE": str(get("inline.send_mode", "enter")),
  "CFG_TMUX_AUTOSEND": "1" if b(get("tmux.autosend", True), True) else "0",
  "CFG_TMUX_PASTE_TARGET": str(get("tmux.paste_target", "origin")),
  "CFG_TMUX_POSTPROCESS": "1" if b(get("tmux.postprocess", False), False) else "0",
  "CFG_TMUX_PROCESS_SOUND": "1" if b(get("tmux.process_sound", True), True) else "0",
  "CFG_TMUX_MODE": str(get("tmux.mode", "code")),
  "CFG_TMUX_SEND_MODE": str(get("tmux.send_mode", "auto")),
  "CFG_DEBUG_KEEP_LOGS": "1" if b(get("debug.keep_logs", False), False) else "0",
  "CFG_SWIFTBAR_ENABLED": "1" if b(get("integrations.swiftbar.enabled", True), True) else "0",
  "CFG_UI_KEYBIND_TMUX": str(get("ui.keybinds.tmux", "F12")),
  "CFG_UI_KEYBIND_INLINE": str(get("ui.keybinds.inline", "F11")),
  "CFG_CLEAN_REPEATS_LEVEL": str(get("clean.repeats_level", "1")),
}

mode_llm_overrides = get("postprocess.mode_llm_overrides", {}) or {}
if isinstance(mode_llm_overrides, dict):
  mode_llm_parts = []
  for mode, llm in mode_llm_overrides.items():
    if isinstance(llm, str) and llm.strip():
      mode_llm_parts.append(f"{mode}={llm.strip()}")
  out["CFG_POSTPROCESS_MODE_LLM_OVERRIDES"] = ";".join(sorted(mode_llm_parts))

budget_profiles = get("postprocess.budget_profiles", {}) or {}
if isinstance(budget_profiles, dict):
  budget_llm_parts = []
  budget_max_parts = []
  budget_chunk_parts = []
  for profile, d in budget_profiles.items():
    if not isinstance(d, dict):
      continue
    llm = d.get("llm")
    if isinstance(llm, str) and llm.strip():
      budget_llm_parts.append(f"{profile}={llm.strip()}")
    mt = d.get("max_tokens")
    if isinstance(mt, int):
      budget_max_parts.append(f"{profile}={mt}")
    cw = d.get("chunk_words")
    if isinstance(cw, int):
      budget_chunk_parts.append(f"{profile}={cw}")
  out["CFG_POSTPROCESS_BUDGET_PROFILE_LLM_OVERRIDES"] = ";".join(sorted(budget_llm_parts))
  out["CFG_POSTPROCESS_BUDGET_PROFILE_MAX_TOKENS_OVERRIDES"] = ";".join(sorted(budget_max_parts))
  out["CFG_POSTPROCESS_BUDGET_PROFILE_CHUNK_WORDS_OVERRIDES"] = ";".join(sorted(budget_chunk_parts))

for k, v in out.items():
  print(f"{k}={shlex.quote(v)}")
PYEOF
  )"
}

config_schema_status() {
  if [[ -n "${CFG_CONFIG_PARSE_ERROR:-}" ]]; then
    echo "invalid"
    return 0
  fi
  local raw="${CFG_META_CONFIG_VERSION:-}"
  if [[ "$raw" =~ ^[0-9]+$ ]] && (( raw == DICTATE_CONFIG_SCHEMA_VERSION )); then
    echo "ok"
  else
    echo "mismatch"
  fi
}

config_schema_version_label() {
  if [[ -n "${CFG_CONFIG_PARSE_ERROR:-}" ]]; then
    printf "invalid"
    return 0
  fi
  local raw="${CFG_META_CONFIG_VERSION:-}"
  if [[ "$raw" =~ ^[0-9]+$ ]]; then
    printf "v%s" "$raw"
  else
    printf "unset"
  fi
}
